 evidence={'build':'1002i1','account_rows':rows,'summary':s,'verification':v,'reproduction':rep,'selection':sel,'uncertainty':unc,'diagnostics':diag,'activity':activity,'forecast':fore,'scope':'BTC-only development; 24-response path forecasting and advance-planned clocks; no added information versus price controls; no accepted strategy'};(DOWN/'btc-path-evidence.json').write_bytes(canonical(evidence))
